window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-939360da1f94f36f"]={"versions": [{"id": "FIG-939360da1f94f36f", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) zur Veranschaulichung des Übertragungsmodus „Mixed Transmission Mode“ (TM Mixed) im AUTOSAR Communication Stack (COM). Das Diagramm stellt das Sende- und Wiederholungsverhalten von I-PDUs bzw. Signalen auf einer horizontalen Zeitachse t dar, gesteuert durch zyklische Timer, ereignisgesteuerte Trigger und Mindestabstandsüberwachungen (Minimum Delay Time, MDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Referenzachse des zeitlichen Ablaufs.\n</li><li><strong>Sendeereignisse (grüne vertikale Pfeile)</strong>: Tatsächliche I-PDU-Sendeaufrufe (Transmit-Trigger an den darunterliegenden Interface-/Bus-Treiber).\n</li><li><strong>Zykluszeit (t_c)</strong>: Parametrierte zyklische Sendeperiode (Cycle Time).\n</li><li><strong>Zyklusverschiebung / Zyklusrestzeit (dt, &gt;dt)</strong>: Phasenverschiebung bzw. Zeitdifferenz zwischen zyklischem Raster und asynchronem Sendeereignis.\n</li><li><strong>Ereignis-Trigger (oranger Blitz)</strong>: Asynchroner Schreibzugriff bzw. Signalaktualisierung (V = x) mit Übertragungseigenschaft <code>TRIGGERED</code> durch die Applikation/RTE.\n</li><li><strong>Mindestabstandszeit (t_r, min / Minimum Delay Time)</strong>: Mindestsendeabstand (MDT), der zwischen aufeinanderfolgenden Übertragungen eingehalten werden muss.\n</li><li><strong>Wiederholungsabstand (t_d)</strong>: Parametrierter zeitlicher Abstand zwischen Mehrfachübertragungen (Tx Repetition Period / Transmission Deadline).\n</li><li><strong>Wiederholungsanzahl (n = 3)</strong>: Konfigurierte Anzahl von Sendevorgängen bei Auslösung des Mixed-Events (1 Erstübertragung + 2 Wiederholungen).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre zyklische Phase</strong>: Die I-PDU wird periodisch mit der Zykluszeit t_c ausgesendet.\n</li><li><strong>Ereignisauslösung während Sperrzeit</strong>: Nach einem regulären Sendezeitpunkt erfolgt ein asynchrones Signal-Update (V = x, oranger Blitz) innerhalb des durch dt markierten Fensters, bevor die minimale Wartezeit t_r, min abgelaufen ist.\n</li><li><strong>Verzögerter Erstversand</strong>: Der erste transmissionsbedingte Sendeaufruf des Ereignisses wird verzögert, bis die minimale Verzugszeit t_r, min verstrichen ist.\n</li><li><strong>Wiederholungssequenz (n = 3)</strong>: Unmittelbar nach Ablauf von t_r, min wird die PDU gesendet (1. Sendevorgang). Daraufhin folgen im festen zeitlichen Wiederholungsabstand t_d zwei weitere Übertragungen (2. und 3. Sendevorgang), sodass in Summe n = 3 Ereignisübertragungen stattfinden.\n</li><li><strong>Wiedereintritt in das zyklische Raster</strong>: Nach Abschluss der Wiederholungsphase wird das periodische Senden im Abstand t_c fortgesetzt. Die verbleibende Zeit bis zum nächsten regulären Zyklusimpuls ist &gt;dt, gemessen ab dem letzten Wiederholungsversand.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR COM Transmission Modes</strong>: Veranschaulicht Use Case 5a für Signale/Signal-Gruppen mit Transmission Mode <code>Mixed</code> ohne Transmission Mode Selector (TMS) Umschaltung.\n</li><li><strong>Interaktionsregeln MDT vs. Trigger</strong>: Tritt ein <code>TRIGGERED</code>-Ereignis während einer aktiven Mindestsendeabstandszeit (t_r, min) auf, darf die Übertragung erst exakt mit Ablauf von t_r, min erfolgen.\n</li><li><strong>Mehrfachübertragung</strong>: Bei n = 3 werden bei einem Event-Trigger insgesamt 3 PDU-Übertragungen ausgeführt (1 Erstsendung + n-1 Wiederholungen im Abstand t_d).\n</li><li><strong>Zyklusneustart / Resynchronisation</strong>: Nach Beendigung des Burst-Sendezyklus wird der periodische Zyklus t_c neu referenziert bzw. fortgeführt, wobei sichergestellt wird, dass nachfolgende zyklische Sendezeitpunkte die Mindestabstands- und Zykluskriterien einhalten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-af4ad3b7e7034f62", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) zur Veranschaulichung des Übertragungsmodus „Mixed Transmission Mode“ (TM Mixed) im AUTOSAR Communication Stack (COM). Das Diagramm stellt das Sende- und Wiederholungsverhalten von I-PDUs bzw. Signalen auf einer horizontalen Zeitachse t dar, gesteuert durch zyklische Timer, ereignisgesteuerte Trigger und Mindestabstandsüberwachungen (Minimum Delay Time, MDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Referenzachse des zeitlichen Ablaufs.\n</li><li><strong>Sendeereignisse (grüne vertikale Pfeile)</strong>: Tatsächliche I-PDU-Sendeaufrufe (Transmit-Trigger an den darunterliegenden Interface-/Bus-Treiber).\n</li><li><strong>Zykluszeit (t_c)</strong>: Parametrierte zyklische Sendeperiode (Cycle Time).\n</li><li><strong>Zyklusverschiebung / Zyklusrestzeit (dt, &gt;dt)</strong>: Phasenverschiebung bzw. Zeitdifferenz zwischen zyklischem Raster und asynchronem Sendeereignis.\n</li><li><strong>Ereignis-Trigger (oranger Blitz)</strong>: Asynchroner Schreibzugriff bzw. Signalaktualisierung (V = x) mit Übertragungseigenschaft <code>TRIGGERED</code> durch die Applikation/RTE.\n</li><li><strong>Mindestabstandszeit (t_r, min / Minimum Delay Time)</strong>: Mindestsendeabstand (MDT), der zwischen aufeinanderfolgenden Übertragungen eingehalten werden muss.\n</li><li><strong>Wiederholungsabstand (t_d)</strong>: Parametrierter zeitlicher Abstand zwischen Mehrfachübertragungen (Tx Repetition Period / Transmission Deadline).\n</li><li><strong>Wiederholungsanzahl (n = 3)</strong>: Konfigurierte Anzahl von Sendevorgängen bei Auslösung des Mixed-Events (1 Erstübertragung + 2 Wiederholungen).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre zyklische Phase</strong>: Die I-PDU wird periodisch mit der Zykluszeit t_c ausgesendet.\n</li><li><strong>Ereignisauslösung während Sperrzeit</strong>: Nach einem regulären Sendezeitpunkt erfolgt ein asynchrones Signal-Update (V = x, oranger Blitz) innerhalb des durch dt markierten Fensters, bevor die minimale Wartezeit t_r, min abgelaufen ist.\n</li><li><strong>Verzögerter Erstversand</strong>: Der erste transmissionsbedingte Sendeaufruf des Ereignisses wird verzögert, bis die minimale Verzugszeit t_r, min verstrichen ist.\n</li><li><strong>Wiederholungssequenz (n = 3)</strong>: Unmittelbar nach Ablauf von t_r, min wird die PDU gesendet (1. Sendevorgang). Daraufhin folgen im festen zeitlichen Wiederholungsabstand t_d zwei weitere Übertragungen (2. und 3. Sendevorgang), sodass in Summe n = 3 Ereignisübertragungen stattfinden.\n</li><li><strong>Wiedereintritt in das zyklische Raster</strong>: Nach Abschluss der Wiederholungsphase wird das periodische Senden im Abstand t_c fortgesetzt. Die verbleibende Zeit bis zum nächsten regulären Zyklusimpuls ist &gt;dt, gemessen ab dem letzten Wiederholungsversand.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR COM Transmission Modes</strong>: Veranschaulicht Use Case 5a für Signale/Signal-Gruppen mit Transmission Mode <code>Mixed</code> ohne Transmission Mode Selector (TMS) Umschaltung.\n</li><li><strong>Interaktionsregeln MDT vs. Trigger</strong>: Tritt ein <code>TRIGGERED</code>-Ereignis während einer aktiven Mindestsendeabstandszeit (t_r, min) auf, darf die Übertragung erst exakt mit Ablauf von t_r, min erfolgen.\n</li><li><strong>Mehrfachübertragung</strong>: Bei n = 3 werden bei einem Event-Trigger insgesamt 3 PDU-Übertragungen ausgeführt (1 Erstsendung + n-1 Wiederholungen im Abstand t_d).\n</li><li><strong>Zyklusneustart / Resynchronisation</strong>: Nach Beendigung des Burst-Sendezyklus wird der periodische Zyklus t_c neu referenziert bzw. fortgeführt, wobei sichergestellt wird, dass nachfolgende zyklische Sendezeitpunkte die Mindestabstands- und Zykluskriterien einhalten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-939360da1f94f36f", "to": "FIG-af4ad3b7e7034f62", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
